// Compute health status for each source
const sources = $input.first().json;
const now = Date.now();
const H = 3600 * 1000;

const slaByFrequency = {
  hourly:  2 * H,           // hourly source must have run in last 2h
  daily:   30 * H,          // daily must have run in last 30h
  weekly:  8 * 24 * H,      // weekly must have run in last 8 days
  monthly: 35 * 24 * H,     // monthly within 35 days
  annual:  370 * 24 * H     // annual within 370 days
};

const anomalies = [];
for (const s of sources) {
  const sla = slaByFrequency[s.frequency_label] || (30 * H);
  const lastRunMs = s.last_successful_run ? Date.parse(s.last_successful_run) : 0;
  const elapsed = now - lastRunMs;
  const overSla = elapsed > sla;
  const reasons = [];
  if (overSla) reasons.push(`Last run ${Math.round(elapsed / H)}h ago (SLA: ${Math.round(sla / H)}h)`);
  if (s.consecutive_failures >= 3) reasons.push(`${s.consecutive_failures} consecutive failures`);
  if (s.access_status === 'blocked') reasons.push('Access blocked');
  if (reasons.length > 0) {
    anomalies.push({ ...s, reasons, hours_since_last_run: lastRunMs ? Math.round(elapsed / H) : 'never' });
  }
}

const total = sources.length;
const healthy = total - anomalies.length;

return [{ json: {
  total,
  healthy,
  anomalies,
  anomaly_count: anomalies.length,
  needs_alert: anomalies.length > 0
} }];

const data = $input.first().json;
const rows = data.anomalies.map(a =>
  `<tr><td><strong>${a.source_code}</strong></td><td>${a.source_name}</td><td>${a.frequency_label}</td><td>${a.hours_since_last_run}h</td><td style="color:red">${a.reasons.join('<br>')}</td></tr>`
).join('\n');

const html = `<h2>🚨 AI-DOCTOR — Anomalies de santé des sources</h2>
<p><strong>${data.healthy}/${data.total}</strong> sources fonctionnent correctement.</p>
<p><strong>${data.anomaly_count}</strong> source(s) en anomalie :</p>
<table border="1" cellpadding="6" style="border-collapse:collapse">
<thead><tr><th>Code</th><th>Nom</th><th>Fréquence</th><th>Depuis</th><th>Raison</th></tr></thead>
<tbody>${rows}</tbody></table>
<p>Vérifier les workflows correspondants dans n8n et les logs <code>guideline_ingestion_runs</code> pour diagnostic.</p>`;

return [{ json: { html, count: data.anomaly_count } }];
